CREATE TABLE IF NOT EXISTS store_settings (id INTEGER PRIMARY KEY CHECK(id=1),name TEXT NOT NULL DEFAULT 'ADEGA DIGITAL',accepting_orders INTEGER NOT NULL DEFAULT 0,low_stock_threshold INTEGER NOT NULL DEFAULT 5);
INSERT OR IGNORE INTO store_settings VALUES (1,'ADEGA DIGITAL',0,5);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),unlimited INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,icon TEXT,image_url TEXT,age_restricted INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drink_options (id TEXT PRIMARY KEY NOT NULL,option_group TEXT NOT NULL CHECK(option_group IN ('ice','energy')),name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),unlimited INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,UNIQUE(option_group,name));
CREATE TABLE IF NOT EXISTS orders (order_no INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,public_token TEXT NOT NULL UNIQUE,first_name TEXT NOT NULL,last_name TEXT NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'pending',status TEXT NOT NULL DEFAULT 'received',cash_given_cents INTEGER,total_cents INTEGER NOT NULL CHECK(total_cents>0),receipt_checked INTEGER NOT NULL DEFAULT 0,age_required INTEGER NOT NULL DEFAULT 0,age_checked INTEGER NOT NULL DEFAULT 0,voice TEXT,payment_provider_ref TEXT UNIQUE,paid_at TEXT,ready_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>0),ice_option_id TEXT REFERENCES drink_options(id),energy_option_id TEXT REFERENCES drink_options(id));
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_expiry ON admin_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category,sort_order);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_paid ON orders(payment_status,paid_at);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_drink_options ON drink_options(option_group,active);
